#!/usr/bin/env bash
# usage: stack_prodlike.sh A|B   (A = giới hạn job giống production; B = mở rộng để đo năng lực)
cd /home/ict/secai-opt
BASE=(TRANSLATE_V2_MAX_LLM_CALLS=128 TRANSLATE_V2_PDF_OCR_CONCURRENCY=16 TRANSLATE_V2_MAX_OCR_CALLS=4 TRANSLATE_V2_XLSX_MAX_CELLS=20000 TRANSLATE_V2_MAX_CHUNKS=20000 TRANSLATE_V2_MAX_BLOCKS=100000 TRANSLATE_V2_UPLOAD_RATE_PER_MINUTE=100000 TRANSLATE_V2_LOOKUP_RATE_PER_MINUTE=100000 TRANSLATE_V2_SPECIALIST_TIMEOUT_SECONDS=30 TRANSLATE_V2_MAX_UPLOAD_BYTES=52428800 TRANSLATE_V2_MAX_REQUEST_BYTES=55574528 TRANSLATE_V2_PDF_MAX_PAGES=600 TRANSLATE_V2_PDF_MAX_OCR_PAGES=200 TRANSLATE_V2_MAX_TEXT_CODEPOINTS=3000000 TRANSLATE_V2_JOB_DEADLINE_SECONDS=7200)
if [ "$1" = A ]; then X=(TRANSLATE_V2_MAX_RUNNING_JOBS=2 TRANSLATE_V2_MAX_ACTIVE_PER_IP=5 TRANSLATE_V2_MAX_QUEUED_JOBS=20)
else X=(TRANSLATE_V2_MAX_RUNNING_JOBS=${RUNJOBS:-4} TRANSLATE_V2_MAX_ACTIVE_PER_IP=500 TRANSLATE_V2_MAX_QUEUED_JOBS=500); fi
GW_IMG=secai-agent-gateway:translate-opt-20261011e-gateway WK_IMG=secai-agent-gateway:translate-opt-20261011e-worker ./run_stack.sh "${BASE[@]}" "${X[@]}"
